-- Seed prompt registries for CultureSherpa, GFD, and aiaimate
-- Each registry follows the same scenes_json structure as GFV registries
-- 6 scenes per series to start — expandable from Content Studio admin

-- ─────────────────────────────────────────────────────────────────
-- CultureSherpa: Untranslatable Words series (6 episodes)
-- ─────────────────────────────────────────────────────────────────
INSERT OR IGNORE INTO cms_prompt_registries (id, brand, series_id, type, title, description, scene_count, scenes_json, source_file, created_at, updated_at)
VALUES (
  'cs_untranslatable_words',
  'culturesherpa',
  'cs_untranslatable_words',
  'episode',
  'Untranslatable Words',
  'One word. One feeling. No English equivalent. A visual series exploring the emotional vocabulary other cultures carry that we are still searching for.',
  6,
  '[{"scene_number":1,"label":"Saudade","tagline":"SAUDADE (Portuguese)","duration_seconds":20,"image_prompts":[{"beat":"word_reveal","output_hint":"saudade_reveal.png","prompt":"Minimalist graphic design. The word SAUDADE in warm serif typography against deep navy blue. Below: italic translation ''a melancholic longing for something beloved that is gone''. Dusty rose accent color. Clean negative space. Social-ready 1:1 format. No photorealism."},{"beat":"visual_metaphor","output_hint":"saudade_scene.png","prompt":"Impressionistic illustration: empty chair at a sun-faded kitchen table, afternoon light through gauze curtain, a single coffee cup half full. Warm amber palette. Gentle grain texture. Flat illustration style, slightly editorial. No text."},{"beat":"caption_card","output_hint":"saudade_card.png","prompt":"Clean typography card. Dark warm background. Large bold text: ''Some feelings only have a name in other languages.'' Subtext small: @CultureSherpa. Muted palette, modern layout."}],"caption":"Saudade (Portuguese): the melancholic longing for something you love that is gone — or perhaps never was. Some feelings only have a home in other languages. #CultureSherpa #Untranslatable #Portuguese","hashtags":["#CultureSherpa","#Untranslatable","#Portuguese","#Language","#WordNerd"]},{"scene_number":2,"label":"Hygge","tagline":"HYGGE (Danish/Norwegian)","duration_seconds":22,"image_prompts":[{"beat":"word_reveal","output_hint":"hygge_reveal.png","prompt":"Minimalist graphic. HYGGE in clean rounded sans-serif. Soft cream background. Warm candlelight yellow accent. Translation: ''a quality of coziness and comfortable conviviality''. Social 1:1 format."},{"beat":"visual_metaphor","output_hint":"hygge_scene.png","prompt":"Flat illustration: cozy interior, low lamplight, two mugs of tea on a wooden table, soft wool blanket draped over a chair, rain implied outside frosted window. Warm amber and cream palette. No people, just the objects. Hygge as atmosphere."},{"beat":"caption_card","output_hint":"hygge_card.png","prompt":"Typography card. Cream background, warm brown text. Large: ''The Danes built a whole lifestyle around this feeling.'' Small: @CultureSherpa. Clean modern layout."}],"caption":"Hygge (Danish/Norwegian): the art of building coziness, safety, and warmth — not a mood, but a way of being together. Denmark consistently ranks as one of the happiest countries. Coincidence? #Hygge #CultureSherpa #Danish","hashtags":["#Hygge","#CultureSherpa","#Danish","#Cozy","#Happiness"]},{"scene_number":3,"label":"Wabi-Sabi","tagline":"WABI-SABI (Japanese)","duration_seconds":20,"image_prompts":[{"beat":"word_reveal","output_hint":"wabisabi_reveal.png","prompt":"Minimalist graphic. WABI-SABI in brushstroke-inspired typography, charcoal ink on warm off-white. Translation: ''the beauty of imperfection and impermanence''. Subtle paper texture. Japanese aesthetic, social-ready."},{"beat":"visual_metaphor","output_hint":"wabisabi_scene.png","prompt":"Flat illustration: a cracked clay bowl repaired with gold (kintsugi), resting on aged wood, one dried flower leaning against it. Soft natural light. Earthy tones — terracotta, moss, cream. The cracks are beautiful."},{"beat":"caption_card","output_hint":"wabisabi_card.png","prompt":"Typography card. Off-white background. Brushstroke underline on large text: ''Nothing is perfect. Nothing lasts. Nothing is finished.'' Small: @CultureSherpa. Wabi-sabi aesthetic."}],"caption":"Wabi-Sabi (Japanese): finding beauty in imperfection, impermanence, and incompleteness. The cracked bowl is more interesting for its cracks. #WabiSabi #Japanese #CultureSherpa #Mindfulness","hashtags":["#WabiSabi","#Japanese","#CultureSherpa","#Imperfection","#Aesthetic"]},{"scene_number":4,"label":"Fernweh","tagline":"FERNWEH (German)","duration_seconds":18,"image_prompts":[{"beat":"word_reveal","output_hint":"fernweh_reveal.png","prompt":"Clean graphic. FERNWEH bold sans-serif on deep blue-gray. Gold accent line. Translation: ''farsickness — an ache for distant places you have never been''. Wanderlust aesthetic. Social 1:1."},{"beat":"visual_metaphor","output_hint":"fernweh_scene.png","prompt":"Flat editorial illustration: a figure standing at a window, looking at mountains in the distance, a suitcase open but unpacked on the floor. Cool blue-gray palette with warm gold horizon. Emotional, not literal."},{"beat":"caption_card","output_hint":"fernweh_card.png","prompt":"Typography card. Deep slate background, light text. Large: ''Homesick for a place you have never been.'' Small: @CultureSherpa. Clean typographic hierarchy."}],"caption":"Fernweh (German): farsickness. An ache for places you have never been. We have a word for homesickness — but the Germans knew we also needed one for this. #Fernweh #German #CultureSherpa #Travel","hashtags":["#Fernweh","#German","#CultureSherpa","#Travel","#Wanderlust"]},{"scene_number":5,"label":"Mamihlapinatapai","tagline":"MAMIHLAPINATAPAI (Yaghan)","duration_seconds":24,"image_prompts":[{"beat":"word_reveal","output_hint":"mamihla_reveal.png","prompt":"Graphic card. Long word MAMIHLAPINATAPAI set in small elegant serif across the full width of a dark slate card. Below: the translation and source language in warm amber. One of the most succinct words in the world displayed without apology."},{"beat":"visual_metaphor","output_hint":"mamihla_scene.png","prompt":"Minimalist illustration: two figures across a table, both leaning slightly toward each other, both slightly pulled back — the exact tension of wanting to speak first and hoping the other will. Soft neutral tones. No faces needed."},{"beat":"caption_card","output_hint":"mamihla_card.png","prompt":"Typography card. Dark background. Large centered text: ''That look shared by two people, each wishing the other would initiate something they both desire.'' Small: @CultureSherpa."}],"caption":"Mamihlapinatapai (Yaghan, Tierra del Fuego): that shared glance between two people who both want to start something neither is willing to begin. One of the most succinct words ever documented. The Yaghan had 100 of them. #Language #CultureSherpa #Words","hashtags":["#Language","#CultureSherpa","#Linguistics","#WordNerd","#Yaghan"]},{"scene_number":6,"label":"Meraki","tagline":"MERAKI (Greek)","duration_seconds":20,"image_prompts":[{"beat":"word_reveal","output_hint":"meraki_reveal.png","prompt":"Bright clean graphic. MERAKI in bold confident typography on warm cream. Deep terracotta accent. Translation: ''doing something with soul, creativity, and love — leaving a piece of yourself in your work''. Mediterranean energy."},{"beat":"visual_metaphor","output_hint":"meraki_scene.png","prompt":"Flat illustration: hands shaping clay on a pottery wheel, morning light, paint-stained work table in background. Warm terracotta and cream palette. The act of making, not the product. Energy and care visible."},{"beat":"caption_card","output_hint":"meraki_card.png","prompt":"Typography card. Warm cream background. Large text: ''Leave a piece of yourself in everything you make.'' @CultureSherpa. Bold terracotta type."}],"caption":"Meraki (Greek): to do something with soul — to pour yourself into your work so completely that a piece of you remains in it. The Greeks had a word for what great artists already know. #Meraki #Greek #CultureSherpa #Creative","hashtags":["#Meraki","#Greek","#CultureSherpa","#Creative","#MakeThings"]}]',
  'seed/cs_untranslatable_words.json',
  datetime('now'),
  datetime('now')
);

-- ─────────────────────────────────────────────────────────────────
-- GFD: Portfolio Spotlight series (6 case studies)
-- ─────────────────────────────────────────────────────────────────
INSERT OR IGNORE INTO cms_prompt_registries (id, brand, series_id, type, title, description, scene_count, scenes_json, source_file, created_at, updated_at)
VALUES (
  'gfd_portfolio_spotlights',
  'gfd',
  'gfd_portfolio_spotlights',
  'episode',
  'Portfolio Spotlights',
  'One project. One insight. A behind-the-scenes look at how Brett Weaver builds digital products that actually work.',
  6,
  '[{"scene_number":1,"label":"The Dashboard Problem","tagline":"CASE STUDY: ELIASSEN GROUP","duration_seconds":22,"image_prompts":[{"beat":"project_card","output_hint":"eliassen_card.png","prompt":"Professional dark-mode UI screenshot mockup. Dashboard with data visualization — bar charts, KPI tiles, clean data table. Dark charcoal background, white text, accent color teal or electric blue. Modern enterprise SaaS aesthetic. No actual branding. Labeled ''Business Intelligence Dashboard''."},{"beat":"insight_card","output_hint":"eliassen_insight.png","prompt":"Typography card. Dark background. Bold white text: ''The data was there. The story wasn''t.'' Subtext: ''How we turned a spreadsheet into a decision engine.'' Good Flippin Design wordmark bottom right."},{"beat":"results_card","output_hint":"eliassen_results.png","prompt":"Results card. Dark charcoal background. Three KPI tiles side by side: ''40% faster reporting'', ''Single source of truth'', ''Exec-ready by 9am''. Clean sans-serif. Professional. Bottom: goodflippindesign.com"}],"caption":"Some data problems aren''t data problems — they''re design problems. Built a BI dashboard for Eliassen Group that turned raw data into executive decisions. The spreadsheet was fine. The story it told wasn''t. #WebDev #DataViz #GoodFlippinDesign","hashtags":["#WebDev","#DataViz","#GoodFlippinDesign","#UX","#Dashboard"]},{"scene_number":2,"label":"Healthcare Data, Human Stakes","tagline":"CASE STUDY: KP STRATEGIC","duration_seconds":20,"image_prompts":[{"beat":"project_card","output_hint":"kp_card.png","prompt":"Healthcare analytics dashboard mockup. Clean light UI, patient data visualization, trend lines, heatmap elements. Professional, clinical precision aesthetic. No real patient data. Medical blue and white color scheme. Labeled ''Healthcare Analytics Platform''."},{"beat":"insight_card","output_hint":"kp_insight.png","prompt":"Typography card. Clean white background. Dark text: ''When the data is about people, clarity is not optional.'' Subtext: ''Healthcare analytics built for impact, not impressions.'' Good Flippin Design wordmark."},{"beat":"results_card","output_hint":"kp_results.png","prompt":"Results card. Light background. Highlight: ''HIPAA-compliant'', ''Real-time population health tracking'', ''Clinical decision support''. Professional healthcare aesthetic."}],"caption":"Healthcare data is different. It''s about people, not metrics. Built KP Strategic''s globalization analytics platform with one principle: every number represents a patient. Clarity isn''t a preference — it''s a responsibility. #Healthcare #DataViz #WebDev","hashtags":["#Healthcare","#DataViz","#WebDev","#GoodFlippinDesign","#UX"]},{"scene_number":3,"label":"When Performance Is the Feature","tagline":"BUILD: PERFORMANCE BY DESIGN","duration_seconds":18,"image_prompts":[{"beat":"project_card","output_hint":"perf_card.png","prompt":"Web performance metrics screenshot. Lighthouse score: 98/100. Core Web Vitals green across the board. Dark devtools aesthetic, clean code. ''Performance audit'' label."},{"beat":"insight_card","output_hint":"perf_insight.png","prompt":"Typography card. Dark charcoal. Large: ''Every 100ms of load time costs you customers.'' Subtext: ''We build fast because fast is a feature.'' GFD wordmark."},{"beat":"results_card","output_hint":"perf_results.png","prompt":"Results card. Dark background. Three values: ''98.6% test coverage'', ''Sub-second load time'', ''Zero build tools''. Clean professional layout."}],"caption":"Performance is not a phase you add at the end. It''s a decision you make at the beginning. Here''s what 98/100 Lighthouse scores look like and why they matter more than they sound. #WebPerformance #Frontend #GoodFlippinDesign","hashtags":["#WebPerformance","#Frontend","#GoodFlippinDesign","#Lighthouse","#CoreWebVitals"]},{"scene_number":4,"label":"The No-Framework Bet","tagline":"PHILOSOPHY: MINIMAL SURFACE AREA","duration_seconds":20,"image_prompts":[{"beat":"project_card","output_hint":"noframework_card.png","prompt":"Split comparison card. Left: complex dependency tree diagram, many boxes, tangled lines, label ''Framework overhead''. Right: single clean HTML file icon, label ''You actually own this''. Dark background, clean design."},{"beat":"insight_card","output_hint":"noframework_insight.png","prompt":"Typography card. Dark background. Bold: ''The best code is the code you don''t have to track down.'' Subtext: ''Why vanilla HTML ships faster and lasts longer than React.'' GFD wordmark."},{"beat":"results_card","output_hint":"noframework_results.png","prompt":"Clean comparison results. Two columns: ''Vanilla HTML/CSS/JS'' vs ''Framework''. Vanilla wins on: deploy time, maintenance cost, longevity, Lighthouse score. Clean minimal table aesthetic."}],"caption":"Hot take: the most maintainable code is the one with the fewest moving parts. I build marketing sites and dashboards in vanilla HTML/CSS/JS — no build step, no framework debt, no migration path. They just keep working. #WebDev #NoFramework #GoodFlippinDesign","hashtags":["#WebDev","#Frontend","#GoodFlippinDesign","#HTML","#Minimal"]},{"scene_number":5,"label":"Accessibility Is Not Optional","tagline":"STANDARD: WCAG AA COMPLIANCE","duration_seconds":22,"image_prompts":[{"beat":"project_card","output_hint":"a11y_card.png","prompt":"Accessibility audit card. Green checkmarks across WCAG 2.1 criteria. Color contrast ratio shown: 7.2:1 (well above the 4.5:1 minimum). Keyboard focus indicator visible. Clean design audit aesthetic."},{"beat":"insight_card","output_hint":"a11y_insight.png","prompt":"Typography card. Dark background. Large: ''1 in 4 Americans has a disability. Inaccessible code isn''t a design flaw — it''s a decision.'' GFD wordmark."},{"beat":"results_card","output_hint":"a11y_results.png","prompt":"Results card. Accessibility metrics: ''44px minimum tap targets'', ''4.5:1+ contrast ratios'', ''Keyboard navigable'', ''Screen reader tested''. Green accent throughout."}],"caption":"Accessibility is not a checklist item. It is the floor of professional web development. Every site I ship is WCAG AA compliant — not because clients ask for it, but because it is right. #Accessibility #WebDev #WCAG #GoodFlippinDesign","hashtags":["#Accessibility","#WebDev","#WCAG","#a11y","#GoodFlippinDesign"]},{"scene_number":6,"label":"Ship Fast, Measure Everything","tagline":"PROCESS: CI/CD THE RIGHT WAY","duration_seconds":20,"image_prompts":[{"beat":"project_card","output_hint":"cicd_card.png","prompt":"GitHub Actions workflow visualization. Green checkmarks, pipeline stages: Test → Build → Deploy. Clean dark developer aesthetic. Cloudflare Pages deploy card visible. Professional."},{"beat":"insight_card","output_hint":"cicd_insight.png","prompt":"Typography card. Dark background. Bold: ''Deploy in 2 minutes. Know in real-time if something breaks.'' Subtext: ''CI/CD is not optional — it is confidence.'' GFD wordmark."},{"beat":"results_card","output_hint":"cicd_results.png","prompt":"Results card. Dark background. Stats: ''6 automated workflows'', ''2-minute deploys to Cloudflare'', ''98.6% test coverage'', ''Auto-rollback on failure''. Clean and confident."}],"caption":"A deploy without tests is a bet. I run 144 automated tests before every push — accessibility, performance, responsive layout, animations. Cloudflare deploys in 2 minutes. If it breaks, I know immediately. #DevOps #CI #GoodFlippinDesign #Cloudflare","hashtags":["#DevOps","#CI","#Cloudflare","#GoodFlippinDesign","#Testing"]}]',
  'seed/gfd_portfolio_spotlights.json',
  datetime('now'),
  datetime('now')
);

-- ─────────────────────────────────────────────────────────────────
-- aiaimate: AI Animation Deep Dives series (6 episodes)
-- ─────────────────────────────────────────────────────────────────
INSERT OR IGNORE INTO cms_prompt_registries (id, brand, series_id, type, title, description, scene_count, scenes_json, source_file, created_at, updated_at)
VALUES (
  'aiaimate_deep_dives',
  'aiaimate',
  'aiaimate_deep_dives',
  'episode',
  'AI Animation Deep Dives',
  'How generative AI is changing what motion design means — one technique, one insight, one experiment at a time.',
  6,
  '[{"scene_number":1,"label":"The Prompt Is the Script","tagline":"TECHNIQUE: PROMPT ENGINEERING FOR MOTION","duration_seconds":22,"image_prompts":[{"beat":"intro_card","output_hint":"prompt_intro.png","prompt":"Dark tech aesthetic. Split screen: left side, clean text prompt for an animation; right side, a resulting AI-generated animation frame. Glowing text, dark background. ''The Prompt Is the Script'' title card. aiaimate wordmark."},{"beat":"example_frame","output_hint":"prompt_frame.png","prompt":"Generative art frame: flowing abstract particle motion, deep space blues and purples, AI-generated feel, single bright focal point. Beautiful, clearly AI-generated aesthetic. No text."},{"beat":"insight_card","output_hint":"prompt_insight.png","prompt":"Typography card. Dark background. Bold: ''Every animation starts with a sentence.'' Subtext: ''Prompt engineering is the new storyboarding.'' aiaimate wordmark bottom."}],"caption":"The most powerful animation tool right now is a text prompt. Prompt engineering IS the new storyboarding — the difference between generic and stunning is in the details of how you describe it. #AIAnimation #PromptEngineering #aiaimate","hashtags":["#AIAnimation","#PromptEngineering","#aiaimate","#GenerativeAI","#MotionDesign"]},{"scene_number":2,"label":"Motion Without Keyframes","tagline":"TECHNIQUE: AI-NATIVE ANIMATION","duration_seconds":20,"image_prompts":[{"beat":"intro_card","output_hint":"nokeyframe_intro.png","prompt":"Clean tech card. Traditional animation timeline with keyframes shown grayed out on left. On right: a single AI prompt generating continuous motion. ''Motion Without Keyframes'' title. Dark background."},{"beat":"example_frame","output_hint":"nokeyframe_frame.png","prompt":"AI-generated animation frame: organic fluid motion, morphing geometric forms, smooth continuous movement implied by motion blur. Electric blue and violet palette. Cinematic feel."},{"beat":"insight_card","output_hint":"nokeyframe_insight.png","prompt":"Typography card. Dark. ''What took 40 keyframes now takes 4 words.'' Subtext: ''AI-native motion design is a different skill set — not a replacement, an evolution.'' aiaimate."}],"caption":"Traditional animation: 40 keyframes per second. AI animation: 4 words, continuous motion. This is not replacing animators — it is creating a new kind of animator. The ones who understand both worlds win. #aiaimate #AIAnimation #MotionDesign","hashtags":["#aiaimate","#AIAnimation","#MotionDesign","#GenerativeAI","#Creative"]},{"scene_number":3,"label":"Style Transfer at Scale","tagline":"TECHNIQUE: CONSISTENT VISUAL IDENTITY","duration_seconds":24,"image_prompts":[{"beat":"intro_card","output_hint":"style_intro.png","prompt":"Grid of 4 animation frames — all different content but clearly the same visual style. Demonstrates style consistency across a series. Dark professional layout. ''Style Transfer at Scale'' title."},{"beat":"example_frame","output_hint":"style_frame.png","prompt":"Single stunning AI animation frame showing clear artistic style: bold graphic outlines, muted palette, grain texture, intentional composition — clearly a part of a branded series. No text. Beautiful."},{"beat":"insight_card","output_hint":"style_insight.png","prompt":"Typography card. Dark background. Bold: ''A brand is a system, not a single piece.'' Subtext: ''How we maintain visual identity across 100 AI-generated frames.'' aiaimate."}],"caption":"The hard part of AI animation is not making one beautiful frame. It is making 100 frames that look like they belong together. Style consistency at scale is the real craft. Here is how we do it. #StyleTransfer #aiaimate #BrandDesign","hashtags":["#StyleTransfer","#aiaimate","#BrandDesign","#AIAnimation","#GenerativeArt"]},{"scene_number":4,"label":"When AI Gets It Wrong","tagline":"HONEST TAKE: FAILURE MODES","duration_seconds":20,"image_prompts":[{"beat":"intro_card","output_hint":"fail_intro.png","prompt":"Honest comparison card. Left: AI-generated animation attempt that clearly went wrong — distorted, uncanny, incorrect. Right: corrected version after human guidance. Dark background. ''When AI Gets It Wrong'' title."},{"beat":"example_frame","output_hint":"fail_frame.png","prompt":"Split panel: top half shows an AI generation failure (weird extra limbs, glitched texture, uncanny valley effect). Bottom half shows clean corrected version. Educational aesthetic."},{"beat":"insight_card","output_hint":"fail_insight.png","prompt":"Typography card. Dark. Bold: ''The AI does not know it is wrong.'' Subtext: ''Human judgment is still the quality gate — and that is the skill.'' aiaimate. Honest, not defensive."}],"caption":"AI gets things wrong — a lot. Extra limbs, physics violations, uncanny valley moments. The skill is not avoiding failure, it is recognizing it fast and correcting the prompt. Human judgment is the quality gate. #aiaimate #AIFails #Honest","hashtags":["#aiaimate","#AIFails","#GenerativeAI","#HonestTake","#MotionDesign"]},{"scene_number":5,"label":"Sound and Motion, Together","tagline":"TECHNIQUE: AUDIO-REACTIVE ANIMATION","duration_seconds":22,"image_prompts":[{"beat":"intro_card","output_hint":"audio_intro.png","prompt":"Dark card showing audio waveform on one side, an animation frame that mirrors the waveform energy on the other. ''Sound and Motion, Together'' title. aiaimate wordmark. Electric energy."},{"beat":"example_frame","output_hint":"audio_frame.png","prompt":"AI animation frame: particle systems, wave forms, pulsing light — clearly reactive to sound/music. Dark background, cyan and purple energy. Beautiful generative audio visualization aesthetic."},{"beat":"insight_card","output_hint":"audio_insight.png","prompt":"Typography card. Dark. ''Music tells you what the animation wants to feel.'' Subtext: ''We start with the track, not the timeline.'' aiaimate."}],"caption":"We start every aiaimate project by listening. The music is not added to the animation — the animation is discovered through the music. Sound-reactive AI motion design is a completely different workflow. Here is what that looks like. #aiaimate #AudioReactive #MotionDesign","hashtags":["#aiaimate","#AudioReactive","#MotionDesign","#SoundDesign","#GenerativeAI"]},{"scene_number":6,"label":"The Loop Problem","tagline":"TECHNIQUE: SEAMLESS AI LOOPS","duration_seconds":20,"image_prompts":[{"beat":"intro_card","output_hint":"loop_intro.png","prompt":"Dark tech card. Circular loop diagram with AI generation in the center. Shows the challenge of seamless looping in AI animation. ''The Loop Problem'' title. aiaimate."},{"beat":"example_frame","output_hint":"loop_frame.png","prompt":"Generative art frame: abstract pattern that clearly tiles and loops — organic but mathematical, seamlessly repeatable. Deep ocean blues, bioluminescent accents. Beautiful and endless."},{"beat":"insight_card","output_hint":"loop_insight.png","prompt":"Typography card. Dark background. ''A 4-second loop that never gets old is harder than a 4-minute video.'' Subtext: ''The art of constraints in AI animation.'' aiaimate."}],"caption":"The hardest thing in AI animation is not the epic scene — it is the perfect loop. A 4-second loop running on a display wall has to work from frame 1 to frame 240 and back to frame 1 without a seam. Here is how we solve it. #aiaimate #LoopAnimation #AIAnimation","hashtags":["#aiaimate","#LoopAnimation","#AIAnimation","#MotionDesign","#Technique"]}]',
  'seed/aiaimate_deep_dives.json',
  datetime('now'),
  datetime('now')
);
